"use strict";
AL.UI = (()=>{
  const K=AL.Core,D=AL.Data,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let page='aquariums',category='fish',fishFilter='habitat',toastTimer,modalOpen=false,nonce=0,lastAction='',lastActionAt=0;
  let placement=null;
  const session=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);
  const nav=[['aquariums','▤','Aquariums'],['store','⌑','Aquarium Store'],['journal','▧','Field Journal'],['equipment','⌘','Equipment'],['casino','dock','The Dock Casino'],['vip','♔','VIP Store'],['settings','⚙','Settings']];
  const fmt=n=>Math.floor(n).toLocaleString('en-US'),button=(label,action,args={},cls='',disabled=false)=>`<button class="${cls}" data-action="${action}" data-args="${esc(JSON.stringify(args))}" ${disabled?'disabled':''}>${label}</button>`;
  const empty=message=>`<div class="empty-state">${message}</div>`,head=(title,text)=>`<h2>${title}</h2><p class="intro">${text}</p>`;
  function toast(message,error=false){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').className='visible'+(error?' error':'');document.querySelectorAll('.modal-feedback').forEach(n=>n.remove());const active=$('dialog').open?$('dialog-body'):$('primary-dialog')?.open?document.querySelector('.primary-header'):$('store-dialog')?.open?document.querySelector('.store-header'):null;if(active){const n=document.createElement('p');n.className='modal-feedback'+(error?' danger-text':'');n.setAttribute('role','status');n.textContent=message;active.append(n);}toastTimer=setTimeout(()=>{$('toast').className='';document.querySelectorAll('.modal-feedback').forEach(n=>n.remove());},5500);}
  function dialog(html){if(placement)cancelPlacement();$('dialog-body').innerHTML=html;$('dialog').showModal();modalOpen=true;}
  function close(){if(AL.DivingUI?.ownsDialog){AL.DivingUI.requestDismiss();return;}$('dialog').close();modalOpen=false;}
  function goto(p,cat){cancelPlacement(false);if(AL.Shell)return AL.Shell.route(p,cat);page=p;render();}
  function save(){if(AL.Startup?.pending)return {ok:false,message:'Choose Continue or Start New Game first.'};const r=AL.Save.save(AL.game);$('save-status').textContent=r.message;return r;}
  function transact(action,args={},token){try{AL.game=K.act(AL.game,action,args,token);save();render();AL.Store?.render();return true;}catch(e){toast(e.message,true);return false;}}
  function selected(){return K.selected(AL.game);}
  function stat(label,value,unit='',status=''){return `<div class="stat-row"><span>${label}</span><strong class="${status}">${value}<small>${unit}</small></strong></div>`;}
  function updateVitals(){const s=AL.game,t=selected(),w=t.waterParams,fish=K.alive(t),day=Math.floor(s.time/1440)+1,h=Math.floor(s.time/60)%24,min=Math.floor(s.time)%60;
    $('level').textContent=String(s.level).padStart(2,'0');$('rank').textContent=s.level<3?'Learning the rhythm':s.level<5?'A growing collection':'Curator of little worlds';$('credits').textContent=fmt(s.credits);$('clock').textContent=`${h>=6&&h<19?'☼':'☾'} Day ${day} · ${AL.Clock.format(s.time)}`;
    $('tank-name').textContent=t.name;$('tank-type').textContent=`${t.water==='fresh'?'FRESHWATER':t.kind==='reef'?'SALTWATER REEF':'SALTWATER'} · ${AL.Units.volume(t.volume)}`;
    const lamps=t.equipment.filter(e=>['light','reefLight'].includes(e.type)),workingLamp=lamps.some(e=>e.durability>0),lit=AL.Sim.light(s,t)>0;
    $('tank-light-mode').value=t.lightMode||'auto';$('tank-light-mode').disabled=!workingLamp;
    $('tank-light-status').textContent=!lamps.length?'No light':!workingLamp?'Light failed':lit?'Light on':'Light off';
    $('tank-light-status').classList.toggle('lit',lit);
    $('livestock-count').textContent=`${fish.length} fish · ${(t.invertebrates||[]).filter(f=>!f.dead).length} invertebrates · ${t.flora.length} ${t.water==='fresh'?'plants':'corals'}`;$('tank-value-amount').textContent=`${fmt(AL.Valuation.tank(s,t).total)} AC`;$('tank-value').onclick=()=>AL.Shell.open('aquariums','value');
    const danger=w.ammonia>.5||w.nitrite>.5||w.oxygen<4,warning=w.ammonia>.2||w.nitrite>.2||w.nitrate>40||w.oxygen<5;
    $('condition').textContent=!t.prepared?'Unprepared':t.bacteria<.65?'Cycling':danger?'Needs care':warning?'Watch closely':'In balance';$('condition').className='pill'+(danger?' danger':warning||t.bacteria<.65?' warn':'');const residentStatus=t.water==='marine'?AL.TankStatus.evaluate(s,t):null;if(residentStatus){$('condition').textContent=residentStatus.label;$('condition').className='pill'+(residentStatus.danger?' danger':residentStatus.label==='Suitable for residents'?'':' warn');$('condition').title=residentStatus.reasons.join(' ');}
    $('water-stats').innerHTML=stat('Temperature',w.temperature.toFixed(1),'°C',(residentStatus?residentStatus.temperatureUnsafe:w.temperature<22||w.temperature>28)?'warn':'good')+(t.water==='marine'?(()=>{const heater=t.equipment.find(e=>e.type==='heater'),model=AL.Heaters.get(heater?.heaterModel);return stat('Heater',!heater?'Missing':!heater.enabled?'Off':heater.durability<=0?'Failed':'On',heater?(model?'L'+model.level+' ? ':'Legacy ? ')+AL.Units.volume(heater.capacity):'')+(heater?stat('Heater condition',heater.durability.toFixed(0),'%',heater.durability<20?'warn':'good'):'');})():'')+stat('pH level',w.ph.toFixed(2),'',t.water==='marine'&&w.ph<8?'warn':'good')+(t.water==='marine'?stat('Salinity',w.salinity.toFixed(1),'ppt',Math.abs(w.salinity-35)>2?'warn':'good'):'')+stat('Ammonia',w.ammonia.toFixed(2),'mg/L',w.ammonia>.25?'danger':'good')+stat('Nitrite',w.nitrite.toFixed(2),'mg/L',w.nitrite>.25?'danger':'good')+stat('Nitrate',w.nitrate.toFixed(1),'mg/L',w.nitrate>40?'warn':'good')+stat('Dissolved oxygen',w.oxygen.toFixed(1),'mg/L',w.oxygen<5?'danger':'good');
    const bio=K.load(t)/K.loadLimit(t)*100;$('bioload-label').textContent=`${Math.round(bio)} / 100`;$('bioload-bar').style.width=Math.min(100,bio)+'%';$('bioload-bar').style.background=bio>85?'var(--gold)':'var(--mint)';
    const warnings=[];if(!t.prepared)warnings.push('Prepare the water before cycling.');else if(t.cycleActive)warnings.push(`Fishless cycle: ${Math.min(100,Math.floor(t.cycle/AL.Config.cycleHours*100))}% · bacteria are establishing.`);else if(t.bacteria<.65)warnings.push('Start the fishless cycle before adding residents.');if(w.ammonia>.25)warnings.push('Ammonia is rising: remove waste and check filtration.');if(w.nitrite>.25)warnings.push('Nitrite is unsafe. Use a prepared water change.');if(w.oxygen<5)warnings.push('Low oxygen: add aeration or reduce stocking.');if(t.fish.some(f=>f.dead))warnings.push('Remove deceased residents to prevent pollution.');if(t.equipment.some(e=>(!e.enabled&&!(t.lightMode==='off'&&['light','reefLight'].includes(e.type)))||e.durability<20))warnings.push('Equipment is disabled or needs service.');if(fish.some(f=>f.hunger>70))warnings.push('Residents are hungry. Check their diets.');$('water-warning').textContent=residentStatus?['General marine chemistry: '+(residentStatus.general?'within general thresholds.':'needs attention.'),...residentStatus.reasons,...warnings].slice(0,5).join(' '):warnings.slice(0,2).join(' ');
    $('scene-status').textContent=placement?'Choose a supported home and depth':t.cycleActive?'The invisible gardeners are at work':fish.length||t.flora.length?'A little world, alive':t.prepared?'Ready for its next chapter':'A world taking shape';if(residentStatus&&!residentStatus.stocked)$('scene-status').textContent='No living stocked aquarium';$('empty-tank').classList.toggle('hidden',fish.length>0||t.fish.length>0||t.flora.length>0||!!placement);$('empty-tank').querySelector('strong').textContent=t.cycleActive?'Good things take a little time.':t.bacteria>=.65?'Your little world is ready for life.':'Every ecosystem starts somewhere.';$('empty-tank').querySelector('span').textContent=t.cycleActive?'Bacteria are turning this water into a home.':'Prepare the water. Let life follow.';$('onboard-action').textContent=!t.prepared?'Prepare your aquarium →':t.cycleActive?'View cycling progress →':t.bacteria<.65?'Establish the ecosystem →':'Meet your first residents →';
    const next=D.quests.find(q=>!s.quests[q.id]&&K.questAvailable(s,q));if(next){$('next-title').textContent=next.title;$('next-description').textContent=next.description;$('quest-progress').innerHTML=`<div class="meter"><i style="width:${K.progress(s,next)/next.target*100}%"></i></div><small>${Math.floor(K.progress(s,next))} / ${next.target} · ${next.reward} AC reward</small>`;}else{$('next-title').textContent='A world well cared for';$('next-description').textContent='Keep growing your collection and enjoy the daily showcase.';$('quest-progress').innerHTML='';}
    $('event-log').innerHTML=s.log.slice(0,4).map(e=>`<div class="log-entry">${esc(AL.Units.text(e.message))}<small>DAY ${Math.floor(e.time/1440)+1} · ${AL.Clock.format(e.time)}</small></div>`).join('');$('season-label').textContent=`${s.season.toUpperCase()} · DAY ${day}`;
    document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===s.settings.speed));
  }
  function speciesCard(d,black=false){const s=AL.game,t=selected(),count=d.group>1?d.group:1,r=K.compatibility(s,t,d.id,count),locked=s.level<d.level;return `<article class="item-card"><img class="sprite-preview" src="${AL.Art.thumb(d.id)}" alt="Pixel sprite of ${esc(d.name)}"><span class="rarity">${d.fictional?'FICTIONAL · CONTRABAND':d.rarity}</span><h3>${d.name}</h3><p>${d.size} cm adult · ${AL.Units.volume(d.minTank)} minimum<br>${d.group>1?`School of ${d.group}+`:'Individual / compatible pair'} · ${d.water==='fresh'?'Freshwater':'Marine'}</p><p class="${r.ok?'good-text':'muted'}">${locked?`Unlocks at level ${d.level}`:r.status}</p><div class="item-bottom"><span class="price">${fmt(d.price)} AC <small>/ fish</small></span>${button('Inspect →','inspectSpecies',{id:d.id},'',locked)}</div><p>${s.stock[d.id]} in stock${black?' · No legal resale':''}</p></article>`;}
  function aquariumPage(){const s=AL.game,t=selected();let onboarding='';if(!AL.Preparation.prepared(t))onboarding=`<div class="notice">${t.water==='marine'?'<strong>'+AL.Preparation.state(t).label+'</strong><br>':''}Your first step: condition the water and set the thermostat. Preparation is included with your aquarium.<div style="margin-top:10px">${t.water==='marine'&&!AL.Preparation.filled(t)?button('Add water','fillWater',{},'')+' ':''}${button('Prepare water','prepare',{},'primary')}</div></div>`;else if(t.bacteria<.65||t.cycleActive)onboarding=`<div class="notice">A new filter has no established bacterial colony. Our accelerated fishless cycle takes 36 game hours. Real aquarium cycling typically takes much longer.<div style="margin-top:10px">${t.cycleActive?button('Finish fishless setup →','finishCycle',{},'primary',s.tanks.some(n=>n.fish.length||n.eggs.length)):button('Start fishless cycle','cycle',{},'primary')}</div>${t.cycleActive?'<small>Skip is available only while every aquarium has no fish or eggs; the simulation still processes every step.</small>':''}</div>`;
    return head('A home, not just a tank','Watch the small things. A well-kept aquarium finds its own rhythm.')+(t.water==='marine'&&AL.Preparation.prepared(t)?'<p class="notice">'+AL.Preparation.state(t).label+'</p>':'')+onboarding+`<div class="stats-grid"><div class="stat-box"><small>Living residents</small><strong>${K.alive(t).length}</strong><small>${new Set(t.fish.map(f=>f.species)).size} species in this aquarium</small></div><div class="stat-box"><small>Biological filter</small><strong>${Math.round(Math.min(t.bacteria,t.bacteria2)*100)}%</strong><small>Two bacterial populations</small></div><div class="stat-box"><small>Balanced water</small><strong>${(t.safeHours/24).toFixed(1)} d</strong><small>Consecutive occupied days</small></div></div><div class="section-title"><h2>Your residents</h2>${button('Browse fish →','navigate',{page:'store',category:'fish'},'text-button')}</div>`+residents(t)+`<div class="row"><div><strong>Daily aquarium showcase</strong><p>Three healthy fish and a day of stable water earn 90 AC. Once per game day.</p></div>${button('Enter showcase','showcase')}</div>`;
  }
  function residents(t){if(!t.fish.length)return empty('The water is quiet for now.<br>Cycle your tank, then choose a compatible resident from the store.');return t.fish.map(f=>`<div class="row"><img src="${AL.Art.thumb(f.species,f.variety)}" width="64" height="40" style="image-rendering:pixelated" alt=""><div style="flex:1"><strong>${esc(f.name)} ${f.dead?'<span class="danger-text">· deceased</span>':''}</strong><p>${D.species[f.species].name} · ${esc(t.water==='marine'?AL.Breeding.role(f):f.sex==='F'?'Female':'Male')} · ${f.dead?esc(f.deathCause):`${Math.round(f.hp)} HP · ${f.behavior} · hunger ${Math.round(f.hunger)}%`}</p></div>${button(f.dead?'Remove':'Inspect','inspectFish',{id:f.id})}</div>`).join('');}
  function storePage(){const s=AL.game,t=selected();const tabs=[['fish','Fish'],['tanks','Aquariums'],['equipment','Equipment'],['food','Food'],['flora','Plants & corals'],['supplies','Supplies'],['decor','Hardscape'],['eggs','Eggs']];let html=head('The aquarium store','Thoughtfully chosen residents and everything they need to thrive.')+`<div class="filter-row">${tabs.map(([id,label])=>button(label,'category',{id},category===id?'active':'')).join('')}</div>`;
    if(category==='fish'){html+=`<div class="filter-row">${button('This habitat','fishFilter',{filter:'habitat'},fishFilter==='habitat'?'active':'')}${button('All species','fishFilter',{filter:'all'},fishFilter==='all'?'active':'')}</div><div class="cards">${Object.values(D.species).filter(d=>!d.fictional&&(fishFilter==='all'||d.water===t.water)).map(d=>speciesCard(d)).join('')}</div>`;}
    if(category==='tanks')html+=tankCatalog();if(category==='equipment')html+=equipmentShop();if(category==='food')html+=foodShop();if(category==='flora')html+=floraShop();if(category==='supplies')html+=`<div class="cards">${Object.entries(D.supplies).map(([id,d])=>`<article class="item-card"><h3>${d.name}</h3><p>${AL.Clock.text(AL.Units.text(d.description))}</p><p>${d.amount} doses · ${s.inventory[id]} owned · ${s.stock[id]} in stock</p><div class="item-bottom"><span class="price">${d.price} AC</span>${button('Buy supplies','buySupply',{type:id})}</div></article>`).join('')}</div>`;
    if(category==='decor')html+=`<div class="cards">${[['cave','Riverstone cave','Shelter lowers aggression and supports breeding.',45],['wood','Branching driftwood','A hiding place and courtship habitat.',45],['lantern',s.season+' lantern','A lasting seasonal decoration. It also provides cover.',60]].map(([id,name,text,price])=>`<article class="item-card"><h3>${esc(name)}</h3><p>${text}</p><div class="item-bottom"><span class="price">${price} AC</span>${button('Place in tank','decorate',{type:id})}</div></article>`).join('')}</div>`;
    if(category==='eggs')html+=`<div class="notice">Eggs are placed directly into your selected aquarium. They need suitable water and reserved adult space.</div><div class="cards">${['danio','clown'].map(id=>{const d=D.species[id];return `<article class="item-card"><img class="sprite-preview" src="${AL.Art.thumb(id)}" alt="${d.name}"><h3>${d.name} egg</h3><p>One fertilized egg · ${d.incubation} suitable hours · fry need fine food.</p><div class="item-bottom"><span class="price">${Math.floor(d.price*.6)} AC</span>${button('Incubate','buyEgg',{species:id})}</div></article>`;}).join('')}</div>`;return html;
  }
  function tankCatalog(){return `<div class="cards">${D.sizes.map(d=>`<article class="item-card"><span class="rarity">${d.volume<150?'A SMALL BEGINNING':'ROOM TO GROW'}</span><h3>${d.name}</h3><div class="stat-box"><strong>${AL.Units.volume(d.volume)}</strong></div><p>Empty and dry. Equipment and hardscape are purchased separately.<br>${d.marinePrice!==undefined?'Saltwater shell purchase: '+d.marinePrice+' AC total. Life support and upkeep are separate.':'Marine shell costs 25% more.'}<br>Unlocks at keeper level ${d.level}.</p><div class="item-bottom"><span class="price">${fmt(d.price)} AC</span>${button('Configure →','configureTank',{volume:d.volume},'',AL.game.level<d.level)}</div></article>`).join('')}</div>`;}
  function equipmentShop(){const t=selected();return `<div class="cards">${Object.entries(D.equipment).filter(([id,d])=>!d.water||d.water===t.water).map(([id,d])=>`<article class="item-card"><h3>${d.name}</h3><p>${AL.Clock.text(AL.Units.text(d.description))}</p><p>${AL.Units.volume(Math.max(d.capacity,t.volume))} capacity · ${Math.round(d.watts*Math.max(d.capacity,t.volume)/d.capacity)} W<br>${AL.game.stock[id]} in stock</p><div class="item-bottom"><span class="price">${fmt(Math.ceil(d.price*Math.max(1,t.volume/d.capacity)))} AC</span>${button(t.equipment.some(e=>e.type===id)?'Installed':'Install','buyEquipment',{type:id},'',t.equipment.some(e=>e.type===id))}</div></article>`).join('')}</div>`;}
  function foodShop(){return `<div class="cards">${Object.entries(D.foods).map(([id,d])=>`<article class="item-card"><h3>${d.name}</h3><p>${Math.round(d.protein*100)}% protein · ${Math.round(d.plant*100)}% plant content<br>Quality ${Math.round(d.quality*100)}% · particle ${d.particle} mm<br>20 portions · ${AL.game.inventory[id]} owned · ${AL.game.stock[id]} in stock</p><div class="item-bottom"><span class="price">${d.price} AC</span>${button('Buy food','buyFood',{type:id})}</div></article>`).join('')}</div>`;}
  function floraShop(){return `<div class="cards">${Object.entries(D.flora).filter(([id,d])=>d.water===selected().water).map(([id,d])=>`<article class="item-card"><canvas class="flora-preview" data-flora="${id}" width="180" height="80" aria-label="${d.name}"></canvas><h3>${d.name}</h3><p>${d.water==='marine'?`Reef aquarium · flow ${Math.round(d.flow*100)}%+`:'Consumes nitrate and provides shelter'}<br>Daily light target ${Math.round(d.light*100)}% · ${AL.game.stock[id]} in stock</p><div class="item-bottom"><span class="price">${d.price} AC</span>${button(d.water==='marine'?'Place coral →':'Add to aquarium',d.water==='marine'?'beginCoral':'buyFlora',{type:id})}</div></article>`).join('')}</div>`;}
  function collectionPage(){return head('Living colors','Every resident is an individual. Select one to see health, diet, genetics, lineage and transfer options.')+residents(selected())+`<div class="section-title" style="margin-top:25px"><h2>Species field guide</h2><small>${AL.game.discovered.length} / ${Object.keys(D.species).length} discovered</small></div><div class="cards">${Object.values(D.species).map(d=>`<article class="item-card"><img class="sprite-preview" src="${AL.Art.thumb(d.id)}" alt="${d.name}"><span class="rarity">${AL.game.discovered.includes(d.id)?'DISCOVERED':'UNDISCOVERED'}</span><h3>${d.name}</h3><p>${AL.Units.text(d.notes)}</p>${button('Species notes','inspectSpecies',{id:d.id},'text-button')}</article>`).join('')}</div>`;}
  function equipmentPage(){const t=selected();return head('Quietly keeping things alive','Equipment wears gradually. Service it before durability reaches zero. Costs scale with aquarium volume.')+(t.water==='marine'?(AL.MortalityUI?.thermalPanel(AL.game,t)||''):'')+t.equipment.map(e=>`<div class="row"><div><strong>${D.equipment[e.type].name} <small>${e.enabled&&e.durability>0?'Running':'Off'}</small></strong><p>${Math.round(e.durability)}% durability · rated ${AL.Units.volume(e.capacity)} · ${Math.round(D.equipment[e.type].watts*e.capacity/D.equipment[e.type].capacity)} W</p></div><div class="row-actions">${button(e.enabled?'Off':'On','toggleEquipment',{type:e.type})}${button(`Service · ${Math.ceil((100-e.durability)/100*D.equipment[e.type].price*.3*Math.max(1,e.capacity/D.equipment[e.type].capacity))} AC`,'service',{type:e.type})}${button('Move','moveEquipmentDialog',{type:e.type})}</div></div>`).join('')+(t.water==='marine'&&t.kind==='quarantine'?button('Prepare bare quarantine habitat','bareQuarantine'): '')+`<form data-form="controls"><div class="two-col"><label class="field">Target temperature (°C)<input name="temperature" type="number" min="18" max="30" step="0.5" value="${t.temperatureTarget}" required></label><label class="field">Lighting duration (hours / day)<input name="hours" type="number" min="4" max="14" value="${t.lightHours}" required></label></div><label class="field">Light intensity<input name="intensity" type="range" min="0.1" max="1" step="0.05" value="${t.lightIntensity}"></label><button class="primary" type="submit">Apply controls</button></form><div style="margin-top:25px">${equipmentShop()}</div>`;}
  function foodPage(){const t=selected();return head('A little, at the right time',t.water==='marine'?'Use species-compatible meals. Marine automatic feeding checks every four game hours and adapts stocked rations to actual diet and life stage; uneaten food still decays.':'Food attracts hungry residents. Uneaten particles decay after two game hours. Feed once or twice a day; young fry need fine food.')+`<form data-form="feed"><div class="two-col"><label class="field">Food choice<select name="type">${Object.entries(D.foods).map(([id,d])=>`<option value="${id}" ${id===t.foodType?'selected':''}>${d.name} · ${AL.game.inventory[id]} portions</option>`).join('')}</select></label><label class="field">Feeding guidance<small>Hungry fish eat suitable food only. A portion scales with resident count; 20 particles may feed a school.</small></label></div><button class="primary" type="submit">Feed one portion</button></form><div class="row"><div><strong>Automatic feeder menu</strong><p>${t.water==='marine'?'Choose a preferred ration. The feeder also uses other compatible stocked foods when needed; checks occur every four game hours.':'Choose the food to dispense at '+AL.Clock.format(540)+' each day.'} Requires an installed feeder.</p></div>${button('Use selected food','setFeeder')}</div>`+K.alive(t).map(f=>`<div class="row"><div><strong>${esc(f.name)}</strong><p>${f.growth<.3?'Fine fry food':D.species[f.species].diet.map(d=>D.foods[d].name).join(', ')}</p></div><span class="${f.hunger>70?'danger-text':'good-text'}">Hunger ${Math.round(f.hunger)}%</span></div>`).join('')+`<div style="margin-top:22px">${foodShop()}</div>`;}
  function floraPage(){const t=selected();return head('The living landscape','Select a coral in the aquarium to inspect it. Place or reposition colonies yourself, and give stinging LPS corals space from their neighbors.')+(t.flora.length?t.flora.map(f=>`<div class="row"><div><strong>${D.flora[f.type].name}</strong><p>${Math.round(f.hp)} HP · growth ${f.size.toFixed(2)}× · ${f.age.toFixed(1)} days old${f.relocationRequired?' - Relocation required: choose a supported mount':''}</p></div><div class="row-actions">${button('Inspect','inspectFlora',{id:f.id})}${button(D.flora[f.type].water==='marine'?'Reposition':'Position','positionFlora',{id:f.id})}${button('Transfer','moveFloraDialog',{id:f.id})}${f.hp<=0?button('Remove','removeFlora',{id:f.id}):button('Sell cutting · 15 AC','trim',{id:f.id},'',f.size<1.5||f.hp<80)}</div></div>`).join(''):empty('Your aquascape is ready for its first living plants or corals.'))+`<div style="margin-top:22px">${floraShop()}</div>`;}
  function breedingPage(){return AL.BreedingUI.dashboard();}
  function questsPage(){const s=AL.game;return head('The keeper’s field journal','Progress comes from caring well. Claim completed entries to earn credits and keeper experience. Every two entries unlock a new level.')+D.quests.map(q=>{const claimed=s.quests[q.id],progress=K.progress(s,q),available=K.questAvailable(s,q);return `<article class="quest-card ${claimed?'claimed':''}"><h3>${claimed?'✓ ':''}${q.title}</h3><p>${q.description}${!available?`<br>Requires: ${q.prerequisites.map(id=>D.quests.find(n=>n.id===id).title).join(', ')}.`:''}</p><div class="meter"><i style="width:${progress/q.target*100}%"></i></div><div class="quest-end"><span>${Math.floor(progress)} / ${q.target} · ${q.reward} AC + 100 XP</span>${button(claimed?'Recorded':available&&progress>=q.target?'Claim reward':'In progress','claim',{id:q.id},'',claimed||!available||progress<q.target)}</div></article>`;}).join('');}
  function marketPage(){const s=AL.game,t=selected();return head('The local exchange','Rehome healthy fish with local collectors. Daily budgets, demand and sale limits keep the economy grounded.')+`<div class="stats-grid"><div class="stat-box"><small>Buyer budget today</small><strong>${fmt(s.market.budget)} AC</strong></div><div class="stat-box"><small>Sales remaining</small><strong>${AL.Config.saleLimit-s.market.sales}</strong></div><div class="stat-box"><small>Demand recovery</small><strong>Daily</strong></div></div>`+(K.alive(t).length?K.alive(t).map(f=>`<div class="row"><div><strong>${esc(f.name)}</strong><p>${Math.round(f.hp)} HP · demand ${Math.round((s.market.demand[f.species]??1)*100)}% · ${D.species[f.species].fictional?'Local resale prohibited':'Legal local exchange'}</p></div>${button(`Rehome · ${K.value(s,f)} AC`,'confirmSale',{id:f.id},'',!AL.Valuation.livestock(s,f).eligible||K.value(s,f)<=0)}</div>`).join(''):empty('No residents are available to rehome.'));}
  function blackPage(){const s=AL.game;return head('The night market','A fictional underground exchange. Every creature here is invented; these are not real-world wildlife trading rules.')+`<div class="notice warning">Open ${AL.Clock.format(1200)}–${AL.Clock.format(240)} · keeper level 4+<br>Specimens arrive at 65 HP with elevated stress. Reinforced containment is mandatory. Weekly fictional inspections have a 12% confiscation risk even with containment. No legal resale.</div>`+(s.level<4?empty('Keep caring for your aquarium.<br>The night market becomes discoverable at keeper level 4.'):!s.stats.nightMarket?button('Discover the night market','discoverMarket',{},'primary'):`<p class="intro">${K.nightOpen(s)?'The lamps are lit. Limited stock is available.':'The shutters are closed until '+AL.Clock.format(1200)+'. Species notes remain available.'}</p><div class="cards">${Object.values(D.species).filter(d=>d.fictional).map(d=>speciesCard(d,true)).join('')}</div><div class="row"><div><strong>Voidfin specter egg</strong><p>Fictional · same habitat and containment restrictions apply.</p></div>${button('Incubate · 540 AC','buyEgg',{species:'voidfin'},'',!K.nightOpen(s))}</div>`);}
  function achievementsPage(){const s=AL.game;return AL.Update29UI.achievement()+head('Things worth remembering','Your collection grows with you. Achievements recognize sustained care and discovery.')+`<div class="stats-grid"><div class="stat-box"><small>Species discovered</small><strong>${s.discovered.length}</strong></div><div class="stat-box"><small>Offspring raised</small><strong>${s.stats.raised}</strong></div><div class="stat-box"><small>Collection assets</small><strong>${fmt(K.assets(s))}</strong></div></div>`+['Five living colors','A new generation','A week in balance'].map((name,i)=>`<div class="row"><div><strong>${s.achievements.includes(name)?'◇':'○'} ${name}</strong><p>${['Discover five species.','Successfully hatch or birth offspring.','Maintain safe occupied water for seven days.'][i]}</p></div><span class="muted">${s.achievements.includes(name)?'Recorded':'Not yet earned'}</span></div>`).join('')+`<div class="notice">Achievements are checked at the next in-game dawn. Showcase rewards are available from the Aquariums screen.</div>`;}
  function vipPage(){return head('A little extra wonder','VIP Preview — Not Available for Purchase.')+`<div class="notice">Cosmetic concepts only. Preview currency: 0 (disabled). There are no paid entitlements, subscriptions or payment functions. Preview lighting is free to try.</div><div class="filter-row">${[['none','Natural'],['moonlight','Moonlit lagoon'],['amber','Golden hour'],['prism','Prism water']].map(([id,name])=>button(name,'preview',{id},AL.game.vip.preview===id?'active':'')).join('')}</div><div class="cards">${[['Bronze','Collector','Cosmetic fish palettes and collector badges.'],['Silver','Specialist','Seasonal scenery and decorative equipment skins.'],['Gold','Aquarium Elite','Display stands and coral color variants.'],['Platinum','Ocean Master','Ambient lighting themes and tank backgrounds.'],['Diamond','Legendary Curator','Animated display effects and prestige badges.']].map(([tier,name,text])=>`<article class="item-card"><span class="rarity">VIP ${tier}</span><h3>${name}</h3><p>${text}</p><p>Future concept · not an implemented entitlement.</p></article>`).join('')}</div>`;}
  function settingsPage(){const s=AL.game;return head('At your own pace','Your aquariums live entirely on this device. Keep a JSON backup when changing browsers, moving the folder or clearing browser data.')+`<div class="notice ${AL.Save.available?'':'warning'}">${AL.Save.locked?'An unreadable save is protected. Use recovery before continuing.':AL.Save.available?'Local saving is available. Autosave runs every 20 seconds and after transactions.':'Browser storage is unavailable. Export a JSON file to preserve progress.'}</div><div class="filter-row">${button('Save now','save')}${button('Export JSON backup','export',{},'primary')}${button('Import JSON backup','import')}${button('Recover previous autosave','recoverDialog')}${AL.Save.hasPreRepair?.(s)?button('Export pre-repair snapshot','exportPreRepair'):''}</div>${AL.GameplayUI.preferences()}${AL.Update29UI.preferences()}<form data-form="settings"><label class="field">Clock format<select name="clockFormat"><option value="24" ${s.settings.clockFormat==='24'?'selected':''}>24 Hour</option><option value="12" ${s.settings.clockFormat==='12'?'selected':''}>12 Hour</option></select></label><p>Continuous offline ecosystem: every 20 real minutes away advances one game day. All elapsed time is processed, including care rewards and survival consequences. Keep your feeders supplied.</p><label class="inline-check"><input name="particles" type="checkbox" ${s.settings.particles?'checked':''}> Ambient particles and bubbles</label><label class="inline-check"><input name="reducedViolence" type="checkbox" ${s.settings.reducedViolence?'checked':''}> Reduce graphic violence (simulation consequences remain)</label><label class="field">Offline seasonal event<select name="season">${['Spring Festival','Summer Ocean','Halloween','Winter Lights','Valentine','Anniversary'].map(v=>`<option ${v===s.season?'selected':''}>${v}</option>`).join('')}</select></label><button class="primary" type="submit">Save preferences</button></form><div class="notice">Game time: 20 real minutes = 1 game day at 1× (72 game minutes per real minute). Pause or accelerate using the aquarium controls. Hidden tabs and closed browsers continue at 1×. Returning processes all elapsed time.</div><div class="row"><div><strong>Start another story</strong><p>Export your current collection first. A new game replaces the active save.</p></div>${button('New game','newGameDialog')}</div><p class="intro">Aquarium Life v3.9 · schema 2 · offline only.<br>Species ranges, lifespans, chemistry rates and breeding periods are simplified game parameters. See GAME_DESIGN.md for biological references and known limits.</p>`;}
  function paintFlora(){document.querySelectorAll('canvas[data-flora]').forEach(c=>{const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;AL.Art.plant(ctx,c.dataset.flora,c.width/2,c.height-5,1.5,0,3);});}
  function render(){const s=AL.game;$('navigation').innerHTML=nav.map(([id,icon,label])=>`<button data-page="${id}" title="${label}" aria-label="${label}${id==='vip'?' — Preview Only':''}"><span class="nav-icon" aria-hidden="true">${id==='casino'?AL.CasinoArt.icon():icon}</span><span class="nav-text">${label}</span>${id==='vip'?'<small>Preview Only</small>':''}</button>`).join('');$('page-title').innerHTML='Your aquariums<span>.</span>';$('aquarium-selector').title=selected().name;$('aquarium-selector').innerHTML=s.tanks.map(t=>`<option value="${esc(t.id)}" ${t.id===s.selectedTank?'selected':''}>${esc(t.name)}</option>`).join('');$('management').innerHTML='';updateVitals();AL.Shell?.render();AL.CasinoUI?.navigation();}
  function waterPage(){const t=selected(),w=t.waterParams;return head('The water laboratory','Small, prepared changes preserve stability. Replacement water is conditioned and matched to this habitat.')+`<div class="two-col"><div>${stat('General hardness (GH)',w.gh.toFixed(1),'°dGH')}${stat('Carbonate hardness (KH)',w.kh.toFixed(1),'°dKH')}${stat('Organic waste',w.organic.toFixed(2),'game units')}${stat('Water clarity',w.clarity.toFixed(0),'%')}</div><div>${stat('Calcium',w.calcium.toFixed(0),'mg/L')}${stat('Magnesium',w.magnesium.toFixed(0),'mg/L')}${stat('Alkalinity',w.alkalinity.toFixed(2),'dKH')}${stat('Phosphate',w.phosphate.toFixed(3),'mg/L')}</div></div><p class="intro">Minerals and phosphate drive reef coral health. GH/KH buffer the simplified freshwater model. Bacterial populations: ammonia oxidizers ${Math.round(t.bacteria*100)}%, nitrite oxidizers ${Math.round(t.bacteria2*100)}%.</p><div class="filter-row">${[.1,.25,.5].map(f=>button(`Change ${f*100}% · ${AL.Units.volume(t.volume*f)} · ${Math.ceil(t.volume*f*(t.water==='marine'?.13:.04))} AC`,'waterChange',{fraction:f})).join('')}</div><p class="intro">Each water change uses one ${t.water==='marine'?'marine salt mix':'conditioner'} dose. You have ${AL.game.inventory[t.water==='marine'?'salt':'conditioner']} doses.</p>${button('Get water supplies →','navigate',{page:'store',category:'supplies'},'text-button')}`;}
  function inspectSpecies(id){if(AL.Data.species[id].water==='marine'&&!AL.Data.species[id].fictional)return AL.Shell.notes(id);const d=D.species[id],t=selected(),count=d.group>1?d.group:1;dialog(`<div class="eyebrow">SPECIES FIELD NOTES${d.fictional?' · FICTIONAL':''}</div><h2>${d.name}</h2><img src="${AL.Art.thumb(id)}" width="192" height="120" style="image-rendering:pixelated;display:block;margin:auto" alt="${d.name}"><p>${AL.Units.text(d.notes)}</p><div class="species-facts"><div><small>Environment</small>${d.water==='fresh'?'Freshwater':'Marine'} · ${AL.Units.volume(d.minTank)} minimum</div><div><small>Adult size / lifespan</small>${d.size} cm · about ${d.life} game years</div><div><small>Temperature / pH</small>${d.temp.join('–')} °C · pH ${d.ph.join('–')}</div><div><small>Diet</small>${d.diet.map(k=>D.foods[k].name).join(', ')}</div><div><small>Social / temperament</small>${d.group>1?`School of ${d.group}+`:'Individual or pair'} · ${d.aggression>.4?'Territorial':'Peaceful / conditional'}</div><div><small>Breeding strategy</small>${d.reproduction} · ${d.incubation} suitable hours</div></div><form data-form="buyFish" data-species="${id}"><label class="field">Number of residents<input name="count" id="purchase-count" type="number" min="1" max="24" value="${count}" required></label><div id="compatibility-report"></div><div class="dialog-actions"><button type="submit" class="primary" id="confirm-fish">Add to ${esc(t.name)}</button></div></form>`);updateCompatibility(id,count);}
  function updateCompatibility(id,count){const d=D.species[id],r=K.compatibility(AL.game,selected(),id,count),eligible=AL.game.level>=d.level&&AL.game.stock[id]>=count&&AL.game.credits>=d.price*count&&(!d.fictional||K.nightOpen(AL.game));$('compatibility-report').innerHTML=`<div class="notice ${r.status!=='Compatible'?'warning':''}"><strong>${r.status} · ${fmt(d.price*count)} AC</strong><br>${[...r.reasons,...r.warnings].map(esc).join('<br>')||'This species meets the current habitat and space requirements.'}${!eligible?'<br>Check your credits, shop stock, keeper level and store opening hours.':''}</div>`;$('confirm-fish').disabled=!r.ok||!eligible;}
  function inspectFish(id){const t=selected(),f=t.fish.find(f=>f.id===id);if(!f)return;AL.renderer.selected=id;const d=D.species[f.species];dialog(`<div class="eyebrow">RESIDENT ${f.id.toUpperCase()} · ${esc(t.water==='marine'?AL.Breeding.role(f):f.sex==='F'?'FEMALE':'MALE')}</div><h2>${esc(f.name)}</h2>${AL.Rarity.badge(f)}<p>${esc(d.scientificName||'Scientific name not recorded')} · Care: ${esc(d.difficulty||'Existing care profile')} · Value: ${AL.Valuation.livestock(AL.game,f).value} AC</p>${AL.Patterns.panel(f)}${d.expansion?'<p>Art status: '+esc(AL.ExpansionArt.metadata(f.species)?.artStatus||d.artStatus)+'</p>':''}<img src="${(AL.Patterns.sprite(f,(f.species==='clown'&&!f.variety&&f.growth>=1&&!f.dead?AL.Art.sprite(f.species):AL.ExpansionArt?.forFish(f)||AL.ClownArt?.forFish(f,0)||AL.LifeStages?.forFish(f)||AL.Art.sprite(f.species)))).toDataURL()}" width="192" height="120" style="image-rendering:pixelated;display:block;margin:auto" alt="${d.name}"><p>${d.name} · ${f.dead?'Deceased: '+esc(f.deathCause):esc(f.behavior)} · ${D.species[f.species].water==='marine'&&AL.Health?'Health details below':f.disease||'No active infection'}</p><div class="species-facts"><div><small>Health / happiness</small>${f.hp.toFixed(0)} HP · ${f.happiness.toFixed(0)}%</div><div><small>Hunger / stress</small>${f.hunger.toFixed(0)}% · ${f.stress.toFixed(0)}%</div><div><small>Age / life stage</small>${f.age.toFixed(0)} days · ${f.age>f.lifeExpectancy?'Elderly':f.growth>=1?'Adult':f.growth<.3?'Fry':'Juvenile'}</div><div><small>Size / energy</small>${(f.adultSize*f.growth).toFixed(1)} cm · ${f.energy.toFixed(0)}%</div><div><small>Fertility / immunity</small>${Math.round(f.fertility*100)}% · ${Math.round(f.immune*100)}%</div><div><small>Generation / parents</small>${f.generation} · ${f.parents.map(esc).join(', ')||'Shop origin'}</div></div>${AL.BreedingUI?.panel(AL.game,t,f)||''}${AL.HealthUI?AL.HealthUI.panel(AL.game,t,f):''}${AL.Update31UI?.fishResearch(f)||''}<p>Genetics · ${Object.entries(f.genes).map(([k,v])=>`${k}: ${v.toFixed(2)}`).join(' · ')}</p><form data-form="renameFish" data-id="${id}"><label class="field">Resident name<input name="name" maxlength="36" value="${esc(f.name)}" required></label><button type="submit">Rename</button></form><div class="dialog-actions">${f.dead?button('Remove remains','removeDead',{id},'primary'):button('Transfer','moveFishDialog',{id})+(d.water==='fresh'&&f.disease?button('Treat infection','treat',{id}):'')+button(f.provenance?.source==='diving'?'Deep Market resale':'View local offer',f.provenance?.source==='diving'?'divingMarket':'confirmSale',{id})}</div>`);}
  function inspectFlora(id,tab='overview'){
    const t=selected(),f=t.flora.find(n=>n.id===id);if(!f)return;
    const d=D.flora[f.type],coral=d.water==='marine',conditions=AL.Sim.floraConditions(AL.game,t,f),c=D.coralCare;
    AL.renderer.selected=id;
    const group=d.scientificName||({zoa:'Zoanthids',mushroom:'Mushroom coral',sps:'Small polyp stony (SPS)',lps:'Large polyp stony (LPS)',soft:'Soft coral'}[f.type]||'Aquatic plant');
    const tabs=['overview','care'].map(name=>`<button role="tab" id="flora-tab-${name}" aria-controls="flora-info-panel" tabindex="${tab===name?0:-1}" aria-selected="${tab===name}" class="${tab===name?'active':''}" data-action="floraTab" data-args="${esc(JSON.stringify({id,tab:name}))}">${name==='overview'?'Overview':'Care'}</button>`).join('');
    const overview=`<div class="species-facts"><div><small>Health</small>${f.hp.toFixed(0)} / 100 HP</div><div><small>Age</small>${f.age.toFixed(1)} game days</div><div><small>Colony growth</small>${f.size.toFixed(2)}× · maximum 2.5×</div><div><small>Color vitality</small>${Math.round(f.color*100)}%</div><div><small>Current Value</small>${AL.Valuation?AL.Valuation.livestock(AL.game,f).value:Math.floor(d.price*f.hp/100*f.size*.5)} AC</div><div><small>Propagation readiness</small>${f.hp>=80&&f.size>=1.5?'Ready for a cutting':'Needs ≥80 HP and 1.5× growth'}</div></div>`;
    const care=`<div class="species-facts"><div><small>Daily light target / current</small>${Math.round(d.light*100)}% / ${Math.round(conditions.dailyLight*100)}%</div><div><small>Light period</small>${conditions.hours} hours/day</div>${coral?`<div><small>Water flow target / current</small>${Math.round(d.flow*100)}% / ${Math.round(conditions.flow*100)}%</div><div><small>Temperature</small>${c.temperature.join('–')} °C · now ${t.waterParams.temperature.toFixed(1)} °C</div><div><small>Salinity</small>${c.salinity.join('–')} ppt · now ${t.waterParams.salinity.toFixed(1)} ppt</div><div><small>Nitrate / ammonia</small>≤${c.maxNitrate} mg/L / near zero</div><div><small>Calcium / magnesium</small>≥${c.minCalcium} / ≥${c.minMagnesium} mg/L</div><div><small>Alkalinity</small>${c.alkalinity.join('–')} dKH</div>`:'<div><small>Nutrients</small>Consumes nitrate while illuminated.</div>'}</div><p>${coral?'Colony growth uses dissolved nutrients and reef minerals. Position it on rockwork or the tank bed. Nearby LPS colonies can sting other living organisms.':'Light supports growth and nutrient uptake. Keep the plant rooted along the tank bed.'}</p>`;
    dialog(`<div class="eyebrow">${coral?'LIVING CORAL':'LIVING PLANT'} · ${esc(id.toUpperCase())}</div><h2>${d.name}</h2>${d.expansion?'<p>Art status: '+esc(AL.ExpansionArt.metadata(f.type)?.artStatus||d.artStatus)+' · '+d.minGallons+' gal minimum</p>':''}${AL.Rarity.badge(f)}<p>Development: ${f.hp<=0?'Deceased':f.size<1?'Frag / young colony':f.size<1.5?'Growing colony':'Mature colony'} · Mount: ${coral?esc(AL.Habitat.definitions[f.type].allowed.join(', ')):'Rooted substrate'}</p><p>${group} · ${f.relocationRequired?'Relocation required':f.hp<=0?'Deceased':conditions.stress>.15?'Conditions need attention':'In suitable conditions'}</p><canvas id="flora-inspect-preview" width="260" height="140" aria-label="${d.name}"></canvas><div class="filter-row" role="tablist" aria-label="Organism information">${tabs}</div><div id="flora-info-panel" role="tabpanel" aria-labelledby="flora-tab-${tab}" tabindex="0">${tab==='care'?care:overview+(coral&&AL.HealthUI?AL.HealthUI.panel(AL.game,t,f):'')}</div><div class="notice ${conditions.issues.length?'warning':''}">${f.hp<=0?'Remove the deceased organism.':conditions.issues.length?conditions.issues.map(esc).join('<br>'):'Light, water and spacing meet this organism’s current game care targets.'}</div><div class="dialog-actions">${coral&&AL.Update31UI?AL.Update31UI.fragButton(f):''}${button(coral?'Reposition':'Position','positionFlora',{id})}${button('Transfer','moveFloraDialog',{id})}${f.hp<=0?button('Remove','removeFlora',{id}):(f.provenance?.source==='diving'?button('Deep Market resale','divingMarket',{id}):button('View individual sale in store','navigate',{page:'marketplace'},'',AL.Update31?!AL.Update31.quote(AL.game,t,f).ok:f.size<1.5||f.hp<80))}</div>`);
    const bounds=AL.Art.plantBounds(f.type,1),scale=Math.min(200/bounds.width,105/bounds.height),ctx=$('flora-inspect-preview').getContext('2d');
    ctx.imageSmoothingEnabled=false;
    AL.Art.plant(ctx,f.type,130,(140+bounds.height*scale)/2,scale,0,Number(id.replace(/\D/g,'')),f.hp/100);
  }
  function inspectRock(id){const t=selected(),r=t.hardscape?.find(r=>r.id===id);if(!r)return;const attached=t.flora.filter(f=>f.attachment?.supportId===id).length;dialog(`<h2>${esc(AL.Habitat.rockProducts[r.group].name)}</h2><p>${attached} attached coral${attached===1?'':'s'}. Supporting rock movement keeps their local attachments. Removal is blocked while coral remains attached.</p><div class="dialog-actions">${button('Position / depth','placeHardscape',{kind:'rock',id})}${button('Move left','moveRock',{id,x:r.x-.03})}${button('Move right','moveRock',{id,x:r.x+.03})}${button('Remove rock','removeRock',{id},'',attached>0)}</div>`);}
  function inspectRack(id){const r=selected().mounts?.find(r=>r.id===id);if(!r)return;const occupied=selected().flora.some(f=>f.attachment?.supportId===id);dialog(`<h2>Mounted frag rack</h2><p>Attached to the ${esc(r.glass)} glass. Moving the rack carries its colonies; relocate them before removing it.</p><div class="dialog-actions">${r.glass==='back'?button('Move left','moveRack',{id,x:r.x-.03,y:r.y})+button('Move right','moveRack',{id,x:r.x+.03,y:r.y}):''}${button('Move up','moveRack',{id,x:r.x,y:r.y-.03})}${button('Move down','moveRack',{id,x:r.x,y:r.y+.03})}${button('Remove rack','removeRack',{id},'',occupied)}</div>`);}
  function beginCoral(type,id,shop={}){
    const t=selected(),f=id?t.flora.find(n=>n.id===id):null,d=D.flora[f?.type||type];
    if(!d||d.water!=='marine')return;
    const eligibility=AL.StoreRules?.report(AL.game,t,'buyFlora',{type,...shop});if(!f&&eligibility&&!eligibility.ok){toast(eligibility.reasons.join(' '),true);return;}
    if(modalOpen)close();AL.Shell?.close(false);
    placement={shopArgs:{...shop},tank:t.id,type:f?.type||type,id:f?.id,x:f?.x??AL.renderer.pan,y:f?(f.y??.92):.82,size:f?.size||1,z:f?.z??.5,token:`${session}-placement-${++nonce}`};
    AL.renderer.placement=placement;page='flora';render();
    $('placement-title').textContent=f?`Reposition ${d.name}`:`Place ${d.name} · ${d.price} AC`;
    $('placement-instructions').textContent='Move the preview and click to place. Arrow keys + Enter work too; Escape cancels.';
    if(shop.mystery)$('placement-title').textContent='Place Mystery Coral - 450 AC. Footprint preview only; species revealed on purchase.';
    $('placement-banner').hidden=false;$('aquarium').classList.add('placing');pointPlacement(placement.x,placement.y);
    $('aquarium').scrollIntoView({block:'center',behavior:'instant'});$('aquarium').focus({preventScroll:true});
  }
  function beginObject(kind,args={},id=null){const t=selected(),object=id?(kind==='rock'?t.hardscape:t.decorations)?.find(o=>o.id===id):null;if(id&&!object)return;AL.Store?.close(false);AL.Shell?.close(false);if(modalOpen)close();const details=object||args;placement={kind,args:{...details},tank:t.id,id,x:object?.x??.5,y:object?.y??.9,z:object?.z??.5,width:kind==='rock'?[38,55,77,90][details.variant]:44,size:1,token:`${session}-placement-${++nonce}`};AL.renderer.placement=placement;$('placement-title').textContent=(id?'Reposition ':'Place ')+(kind==='rock'?AL.Habitat.rockProducts[details.group].name:details.type);$('placement-banner').hidden=false;$('aquarium').classList.add('placing');pointPlacement(placement.x,placement.y);updateVitals();$('aquarium').focus();}
  function shiftDepth(delta){placement.z=Math.round(K.clamp(placement.z+delta,0,1)*10)/10;pointPlacement(placement.x,placement.y);}
  function cancelPlacement(refresh=true){placement=null;AL.renderer.placement=null;$('placement-banner').hidden=true;$('aquarium').classList.remove('placing');if(refresh)updateVitals();}
  function pointPlacement(x,y){if(!placement)return;const report=placement.kind?AL.Placement.report(selected(),placement,x):AL.Habitat?.placement(AL.game,selected(),placement.type,x,y,{size:placement.size,ignoreId:placement.id,z:placement.z});placement.x=report?.ok?report.position.x:x;placement.y=report?.ok?report.position.y:y;placement.valid=report?.ok??true;placement.status=report?.status||'Suitable';placement.message=[...(report?.reasons||[]),...(report?.warnings||[])].join(' ')||'Supported mounting point. Click or press Enter to confirm.';$('placement-instructions').textContent=`Depth ${Math.round(placement.z*100)}% · ${placement.z<.5?'Back':placement.z>.5?'Front':'Middle'} · Wheel / PageUp / PageDown changes depth. `+placement.status+': '+placement.message;}
  function commitPlacement(){
    if(!placement)return;
    const p=placement;if(selected().id!==p.tank){cancelPlacement();return;}
    const report=p.kind?AL.Placement.report(selected(),p,p.x):AL.Habitat?.placement(AL.game,selected(),p.type,p.x,p.y,{size:p.size,ignoreId:p.id,z:p.z});if(report&&!report.ok){toast(report.reasons.join(' '),true);return;}
    if(p.kind){const action=p.args.recoveredId?'diveInstallRock':p.id?(p.kind==='rock'?'moveRock':'moveDecoration'):(p.kind==='rock'?'buyRock':'decorate');if(transact(action,{...p.args,id:p.args.recoveredId||p.id,x:p.x,z:p.z,destinationTankId:p.tank},p.token)){cancelPlacement();toast('Placement saved.');}return;}
    const args=p.id?{id:p.id,z:p.z,x:p.x,y:p.y,destinationTankId:p.tank}:{...p.shopArgs,type:p.type,z:p.z,x:p.x,y:p.y,destinationTankId:p.tank};
    if(transact(p.id?'reposition':p.shopArgs?.mystery?'buyMysteryCoral':'buyFlora',args,p.token)){const f=p.id?selected().flora.find(n=>n.id===p.id):selected().flora.at(-1);AL.renderer.selected=f.id;cancelPlacement();toast(`${D.flora[f.type].name} ${p.id?'repositioned':'placed'}. Select the colony to inspect it.`);}
  }
  function welcome(replace=false){dialog(`<div class="welcome-art" aria-hidden="true">≋ ⋈</div><div class="eyebrow">WELCOME TO AQUARIUM LIFE</div><h2>A small world.<br>Entirely in your care.</h2><p>Build a home, find its balance, and watch it come alive. Your first 20 gal aquarium starts empty and dry. You have food, water supplies and 5,000 Aquarium Credits to choose equipment, build your habitat and prepare safe water.</p>${replace?'<div class="notice warning">Starting a new story replaces the active save. Export your current game first if you want to keep it.</div>':''}<div class="welcome-routes">${button('<strong>The quiet shallows</strong><small>Freshwater · lush plants, colorful schools and a gentler beginning.</small>Begin freshwater →','start',{route:'fresh'},'route-card')}${button('<strong>A pocket of ocean</strong><small>Saltwater reef · bright residents, living corals and a little more care.</small>Begin marine →','start',{route:'marine'},'route-card')}</div><p><small>Completely offline. No accounts. No payments. Just a world worth caring for.</small></p>`);}
  function transfer(action,id){const t=selected(),f=t.fish.find(n=>n.id===id),school=action==='moveFish'&&f&&D.species[f.species].group>1;dialog(`<h2>Choose a new home</h2><p>Destination habitat and capacity are checked before anything moves.${school?'<br>This social species moves with its entire resident school so no fish is left alone.':''}</p><form data-form="transfer" data-action="${action}" data-id="${esc(id)}"><label class="field">Destination<select name="target" required>${AL.game.tanks.filter(n=>n.id!==t.id).map(n=>`<option value="${n.id}">${esc(n.name)} · ${AL.Units.volume(n.volume)}</option>`).join('')}</select></label><button class="primary" type="submit" ${AL.game.tanks.length<2?'disabled':''}>${school?'Transfer entire school':'Transfer'}</button></form>`);}
  function dispatch(action,a={}){
    if(action==="inspectNursery"){AL.game.selectedTank=a.tank;return AL.Update29UI.inspectNursery(a.id);}
    if(action==='healthDetails')return AL.HealthUI.details(a.id);if(action==='medicalInventory')return AL.HealthUI.inventory();if(action==='quarantineDialog')return AL.HealthUI.transfer(a.id,true);if(action==='medicineStore'){close();return AL.Store.open('medicines','saltwater');}if(['examineLivestock','startTreatment','stopTreatment'].includes(action)){if(transact(action,a,`${session}-medical-${++nonce}`))AL.HealthUI.details(a.id);return;}if(action==='assayMedicine'){if(transact(action,a))AL.HealthUI.inventory();return;}
    if(action==='placeHardscape')return beginObject(a.kind,a.args||{},a.id);
    if(action==='inspectEquipment'){const e=selected().equipment.find(e=>e.type===a.type),d=e&&D.equipment[e.type];if(d)return dialog(`<h2>${esc(e.type==='heater'?AL.Heaters.label(e):d.name)}</h2>${e.type==='heater'?AL.MortalityUI.thermalPanel(AL.game,selected()):''}<p>${esc(AL.Clock.text(AL.Units.text(d.description)))}</p><p>${AL.Units.volume(e.capacity)} capacity · ${Math.round(e.durability)}% condition · ${e.enabled?'Enabled':'Disabled'} · ${Math.round(d.watts*e.capacity/d.capacity)} W.</p>`);return;}
    if(action==='journalSpecies')return AL.Shell.notes(a.id);if(action==='journalFlora')return AL.Shell.notes(a.id,true);
    if(action==='notifications')return AL.Shell.open('journal','history');
    if(action==='legacyNotifications')return dialog(`<div class="eyebrow">YOUR AQUARIUM JOURNAL</div><h2>Life lately</h2>${AL.game.log.map(e=>`<div class="log-entry">${esc(AL.Units.text(e.message))}<small>DAY ${Math.floor(e.time/1440)+1} · ${AL.Clock.format(e.time)}</small></div>`).join('')}`);
    if(action==='navigate')return goto(a.page,a.category);if(action==='category'){category=a.id;return render();}if(action==='fishFilter'){fishFilter=a.filter;return render();}
    if(action==='inspectInvertebrate')return AL.ExpansionUI.inspect(a.id);if(action==='invertebrateNotes')return AL.ExpansionUI.notes(a.id);if(action==='invertebrateTransfer')return AL.ExpansionUI.transfer(a.id);if(action==='inspectSpecies'){if(D.species[a.id].water==='marine'&&D.species[a.id].fictional&&!AL.Store?.opened){AL.Store.open('fish','black');return AL.Store.details('fish:'+a.id);}if(AL.Store?.opened)return AL.Store.details('fish:'+a.id);return inspectSpecies(a.id);}if(action==='inspectFish')return inspectFish(a.id);if(action==='inspectFlora')return inspectFlora(a.id);if(action==='floraTab'){inspectFlora(a.id,a.tab);$('flora-tab-'+a.tab).focus();return;}if(action==='beginCoral')return beginCoral(a.type);
    if(action==='start'){if(a.route==='fresh')return toast(AL.Update29.lockText,true);if(AL.Save.locked&&!AL.Startup?.resetAuthorized){toast('Resolve the protected unreadable save first.',true);return;}AL.Save.unlock();AL.game=K.newGame(a.route,undefined,{empty:true});AL.Startup?.finish();AL.Shell?.close(false);close();save();page='aquariums';render();AL.Update29UI.updateTutorial();return;}
    if(action==='configureTank'){const d=D.sizes.find(n=>n.volume===a.volume);return dialog(`<h2>A little more room</h2><p>${d.name} · ${AL.Units.volume(d.volume)} · freshwater ${d.price} AC / marine ${d.marinePrice??Math.ceil(d.price*1.25)} AC</p><form data-form="buyTank" data-volume="${d.volume}"><label class="field">Aquarium name<input name="name" maxlength="36" value="${d.name}" required></label><div class="two-col"><label class="field">Water<select name="water"><option value="marine">Saltwater</option><option value="fresh" disabled>Freshwater - Coming in a Future Update.</option></select></label><label class="field">Purpose<select name="kind"><option value="display">Display</option><option value="reef">Reef (marine only)</option><option value="breeding">Breeding</option><option value="quarantine">Quarantine</option><option value="incubation">Incubation</option></select></label></div><button class="primary" type="submit">Purchase aquarium</button></form>`);}
    if(action==='finishCycle'){if(AL.game.tanks.some(t=>t.fish.length||t.eggs.length))return toast('Fishless skip requires all tanks to be unoccupied.',true);const t=selected();if(!t.cycleActive)return;AL.Sim.advance(AL.game,Math.max(0,AL.Config.cycleHours-t.cycle)*60+5);save();render();toast('The fishless cycle is complete. Your ecosystem is ready.');return;}
    if(action==='setFeeder'){const input=document.querySelector('form[data-form="feed"] select');if(input)transact('controls',{food:input.value});toast('Automatic feeder menu saved.');return;}
    if(action==='preview'){AL.game.vip.preview=a.id;save();render();return;}
    if(action==='moveRack'){if(transact('moveRack',a))inspectRack(a.id);return;}if(action==='removeRack'){if(transact('removeRack',a))close();return;}if(action==='moveRock'){if(transact('moveRock',a))inspectRock(a.id);return;}if(action==='removeRock'){if(transact('removeRock',a))close();return;}if(action==='positionFlora'){const f=selected().flora.find(f=>f.id===a.id);if(!f)return;if(D.flora[f.type].water==='marine')return beginCoral(f.type,f.id);return dialog(`<h2>Find the right spot</h2><p>Use the slider to place ${D.flora[f.type].name} across the aquarium.</p><form data-form="position" data-id="${f.id}"><label class="field">Left ↔ Right<input name="x" type="range" min="0.05" max="0.95" step="0.01" value="${f.x}"></label><button class="primary" type="submit">Place here</button></form>`);}
    if(action==='moveFishDialog')return transfer('moveFish',a.id);if(action==='moveFloraDialog')return selected().water==='marine'&&AL.HealthUI?AL.HealthUI.transfer(a.id,false):transfer('moveFlora',a.id);if(action==='moveEquipmentDialog')return transfer('moveEquipment',a.type);
    if(action==='confirmSale'){const f=selected().fish.find(f=>f.id===a.id);if(!f)return;return dialog(`<h2>A new home for ${esc(f.name)}</h2><p>The local exchange offers ${K.value(AL.game,f)} AC. Selling removes this individual from your aquarium. Check breeding parents and schooling numbers before accepting.</p><div class="dialog-actions">${button('Accept offer','sell',{id:f.id},'primary')}</div>`);}
    if(action==='divingMarket'){close();AL.Store.open('fish','black');document.querySelector('[data-store-mode=sell]').click();return;}if(action==='save'){const r=save();toast(r.message,!r.ok);return;}if(action==='export'){AL.Save.exportSave(AL.game);toast('JSON backup exported.');return;}if(action==='exportPreRepair'){try{AL.Save.exportPreRepair(AL.game);toast('Original pre-repair snapshot exported; restoring livestock still requires your explicit backup restoration.');}catch(e){toast(e.message,true);}return;}if(action==='import')return $('import-file').click();
    if(action==='recoverDialog')return dialog(`<h2>Restore the previous save?</h2><p>This replaces your active game with the last valid browser backup. Export the current game first if needed.</p><div class="dialog-actions">${button('Restore backup','recover',{},'primary')}</div>`);
    if(action==='recover'){try{AL.game=AL.Save.recover();AL.Startup?.finish();close();render();AL.Offline.resume();}catch(e){toast(e.message,true);}return;}
    if(action==='newGameDialog')return AL.Startup.confirm(false);
    if(action==='exportCorrupt'){AL.Save.exportCorrupt();return;}
    if(action==='resetCorrupt')return AL.Startup.confirm(true);
    if(action==='commitImport'){if(!AL.pendingImport)return;try{AL.Offline.importable(AL.pendingImport);}catch(err){toast(err.message,true);return;}AL.game=AL.pendingImport;AL.pendingImport=null;AL.Save.unlock();AL.Startup?.finish();close();render();AL.Offline.resume();return;}
    const key=action+JSON.stringify(a),now=performance.now();if(key===lastAction&&now-lastActionAt<500)return;lastAction=key;lastActionAt=now;
    if(transact(action,a,`ui-${Date.now()}-${++nonce}`)){if(['sell','removeDead','removeBrood','treat','moveFish','removeFlora','moveInvertebrate','sellInvertebrate','removeInvertebrate'].includes(action)&&modalOpen)close();if(action==='trim'&&modalOpen)inspectFlora(a.id);toast({prepare:'Water prepared. Start fishless cycling next.',cycle:'Cycling started. Bacteria need 36 simulated hours.',feed:'Dinner is in the water.',waterChange:'Fresh water, carefully prepared.',claim:'Field journal reward claimed.',breed:'Courtship succeeded. A new brood is developing.'}[action]||'Your aquarium has been updated.');}
  }
  function bind(){document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(AL.Store?.opened&&!target.closest('#store-dialog,#dialog'))return;if(target.dataset.page)goto(target.dataset.page);if(target.dataset.tank){cancelPlacement(false);AL.game.selectedTank=target.dataset.tank;AL.renderer.selected=null;render();save();}if(target.dataset.action)dispatch(target.dataset.action,JSON.parse(target.dataset.args||'{}'));if(target.dataset.speed!==undefined){AL.game.settings.speed=Number(target.dataset.speed);updateVitals();save();}});
    document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const values=Object.fromEntries(new FormData(form)),kind=form.dataset.form;let ok=false;
      if(kind==='buyFish')ok=transact('buyFish',{species:form.dataset.species,count:Number(values.count)},`${session}-purchase-${nonce}`);
      if(kind==='lighting')ok=transact('setLighting',{mode:values.mode})&&transact('controls',{hours:values.hours,intensity:values.intensity});
      if(kind==='buyTank')ok=transact('buyTank',{...values,volume:Number(form.dataset.volume),...(AL.Store?.opened?{destinationTankId:AL.game.selectedTank}:{})},`${session}-tank-${nonce}`);
      if(kind==='renameFish')ok=transact('renameFish',{id:form.dataset.id,name:values.name});if(kind==='renameTank')ok=transact('renameTank',{name:values.name});
      if(kind==='healthTransfer'){const position=JSON.parse(values.position);ok=transact(form.dataset.quarantine==='true'?'quarantineLivestock':'moveFlora',{id:form.dataset.id,target:position.target,x:position.x,y:position.y});}
      if(kind==='transfer')ok=transact(form.dataset.action,{id:form.dataset.id,type:form.dataset.id,target:values.target});if(kind==='position')ok=transact('reposition',{id:form.dataset.id,x:Number(values.x)});
      if(kind==='feed'){ok=transact('feed',{type:values.type});if(ok)toast('Food added. Watch your residents gather.');}if(kind==='controls'){ok=transact('controls',values);if(ok)toast('Environmental controls saved.');}
      if(kind==='settings'){const cap=8;AL.game.settings={...AL.game.settings,clockFormat:values.clockFormat,offline:'survival',offlineCap:Math.max(0,Math.min(8,cap)),particles:!!values.particles,reducedViolence:!!values.reducedViolence};AL.game.season=values.season;save();render();toast('Preferences saved.');return;}
      if(ok&&modalOpen)close();
    });
    document.addEventListener('input',e=>{if(e.target.id==='purchase-count'&&e.target.closest('form')?.dataset.form==='buyFish')updateCompatibility(e.target.closest('form').dataset.species,Number(e.target.value));});
    $('tank-light-mode').onchange=e=>{const mode=e.target.value;if(transact('setLighting',{mode}))toast(mode==='auto'?'Light follows your daily schedule.':mode==='on'?'Aquarium light turned on.':'Aquarium light turned off.');else updateVitals();};
    $('dialog').addEventListener('cancel',e=>{e.preventDefault();close();});$('dialog-close').onclick=close;$('dialog').addEventListener('close',()=>{modalOpen=false;});$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
    $('save-button').onclick=()=>dispatch('save');$('settings-button').onclick=()=>goto('settings');$('new-tank').onclick=()=>AL.Shell.open('aquariums','new');$('aquarium-selector').onchange=e=>{const id=e.target.value;if(!AL.game.tanks.some(t=>t.id===id)){render();return;}cancelPlacement(false);AL.game.selectedTank=id;AL.renderer.selected=null;render();save();};$('quest-link').onclick=()=>goto('quests');$('advanced-water').onclick=()=>AL.Shell.open('aquariums','water');$('onboard-action').onclick=()=>{const t=selected();if(!t.prepared)dispatch('prepare');else if(t.bacteria>=.65&&!t.cycleActive)goto('store','fish');else goto('aquariums');};
    $('rename-tank').onclick=()=>{nonce++;dialog(`<h2>Name your little world</h2><form data-form="renameTank"><label class="field">Aquarium name<input name="name" value="${esc(selected().name)}" maxlength="36" required></label><button class="primary" type="submit">Save name</button></form>`);};
    $('zoom-in').onclick=()=>{AL.renderer.zoom=Math.min(2,AL.renderer.zoom+.25);$('zoom-label').textContent=AL.renderer.zoom+'×';};$('zoom-out').onclick=()=>{AL.renderer.zoom=Math.max(1,AL.renderer.zoom-.25);$('zoom-label').textContent=AL.renderer.zoom+'×';};$('pan-left').onclick=()=>{AL.renderer.pan=Math.max(.5/AL.renderer.zoom,AL.renderer.pan-.1);};$('pan-right').onclick=()=>{AL.renderer.pan=Math.min(1-.5/AL.renderer.zoom,AL.renderer.pan+.1);};
    $('aquarium').addEventListener('wheel',e=>{if(!placement||AL.UI.modalOpen)return;e.preventDefault();shiftDepth(e.deltaY<0?-.1:.1);},{passive:false});
    $('cancel-placement').onclick=()=>cancelPlacement();
    $('aquarium').addEventListener('pointermove',e=>{if(!placement)return;const r=e.target.getBoundingClientRect(),p=AL.renderer.worldPoint((e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height);pointPlacement(p.x,p.y);});
    $('aquarium').onclick=e=>{if(AL.Store?.opened||$('dialog').open||AL.Shell?.opened)return;const r=e.target.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;if(placement){const p=AL.renderer.worldPoint(x,y);pointPlacement(p.x,p.y);commitPlacement();return;}const id=AL.renderer.hit(x,y);if(id){if(selected().decorations.some(r=>r.id===id))return beginObject('decor',{},id);if(selected().mounts?.some(r=>r.id===id))return inspectRack(id);if(selected().hardscape?.some(r=>r.id===id))return inspectRock(id);if(selected().nurseries?.some(n=>n.id===id))return AL.Update29UI.inspectNursery(id);if(selected().invertebrates?.some(f=>f.id===id))return AL.ExpansionUI.inspect(id);if(selected().eggs.some(f=>f.id===id))return AL.BroodView.inspect(id);if(selected().flora.some(f=>f.id===id))inspectFlora(id);else inspectFish(id);}};
    document.addEventListener('keydown',e=>{
      const tab=e.target.closest?.('[role=tab][data-action=floraTab]');
      if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;
      e.preventDefault();
      const {id,tab:current}=JSON.parse(tab.dataset.args),next=e.key==='Home'?'overview':e.key==='End'?'care':current==='care'?'overview':'care';
      inspectFlora(id,next);$('flora-tab-'+next).focus();
    });
    document.addEventListener('keydown',e=>{if(!placement)return;if(e.key==='Escape'){e.preventDefault();cancelPlacement();return;}if(e.target!==$('aquarium'))return;if(['PageUp','PageDown'].includes(e.key)){e.preventDefault();shiftDepth(e.key==='PageUp'?-.1:.1);return;}if(e.key==='Enter'){e.preventDefault();commitPlacement();return;}const directions={ArrowLeft:[-.02,0],ArrowRight:[.02,0],ArrowUp:[0,-.02],ArrowDown:[0,.02]};if(directions[e.key]){e.preventDefault();const [dx,dy]=directions[e.key];pointPlacement(placement.x+dx,placement.y+dy);}});
    $('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Maximum import size is 5 MB.');AL.pendingImport=AL.Save.parse(await file.text());nonce++;dialog(`<h2>Restore this collection?</h2><p>Validated backup: ${AL.pendingImport.tanks.length} aquarium(s), ${AL.pendingImport.tanks.reduce((n,t)=>n+t.fish.length,0)} fish, ${fmt(AL.pendingImport.credits)} AC.<br>This replaces the active game. Export it first if you want to keep both.</p><div class="dialog-actions">${button('Restore backup','commitImport',{},'primary')}</div>`);}catch(err){toast('Import rejected: '+err.message,true);}e.target.value='';};
    document.querySelector('.brand').onclick=e=>{e.preventDefault();goto('aquariums');};
  }
  function recovery(message){dialog(`<div class="eyebrow">YOUR SAVE IS PROTECTED</div><h2>Let’s recover your aquarium.</h2><p>The browser save could not be loaded: ${esc(message)}. It has not been erased or overwritten. Autosaving is suspended.</p><div class="filter-row">${button('Download unreadable save','exportCorrupt')}${button('Restore previous backup','recover')}${button('Import a JSON backup','import')}</div><div class="notice warning">Starting over downloads the unreadable file and allows a new game to replace the browser save.</div>${button('Download old data & start over','resetCorrupt')}`);}
  // Each new purchase dialog gets a unique transaction token shared by repeated submits.
  const originalDialog=dialog;dialog=function(html){nonce++;originalDialog(html);};
  return {views:{aquariums:aquariumPage,water:waterPage,breeding:breedingPage,achievements:achievementsPage,quests:questsPage,vip:vipPage,settings:settingsPage,food:foodPage,market:marketPage},paintFlora,bind,render,updateVitals,toast,welcome,recovery,goto,inspectFish,inspectFlora,save,dialog,close,transact,tankCatalog,beginCoral,cancelPlacement,beginObject,get page(){return page;},get modalOpen(){return modalOpen||!!AL.Store?.opened||!!AL.Shell?.opened;},get placing(){return !!placement;}};
})();
